#!/usr/bin/env bash
set -u
GREEN='\033[0;32m'; RED='\033[0;31m'; NC='\033[0m'
BASE_URL="${BASE_URL:-http://localhost:4000}"; NOTIFICATION_URL="${NOTIFICATION_URL:-http://localhost:4010}"; ADMIN_URL="${ADMIN_URL:-http://localhost:4011}"; API_KEY="${PARTNER_API_KEY:-replace-with-partner-key}"
passed=0; failed=0; skipped=0; body_file=/tmp/smartkitchen-e2e-body; headers_file=/tmp/smartkitchen-e2e-headers
pass_case(){ printf "${GREEN}PASS${NC} %s\n" "$1"; passed=$((passed+1)); }
fail_case(){ printf "${RED}FAIL${NC} %s (method=%s url=%s status=%s expected=%s body=%s)\n" "$1" "$2" "$3" "$4" "$5" "$(head -c 300 "$body_file" 2>/dev/null)"; failed=$((failed+1)); }
call(){ local method="$1" url="$2"; shift 2; curl -sS -D "$headers_file" -o "$body_file" -w '%{http_code}' --max-time 10 -X "$method" "$@" "$url" 2>/tmp/smartkitchen-e2e-curl-error || true; }
status_header(){ tr -d '\r' < "$headers_file" | awk -F': ' -v key="$1" 'tolower($1)==tolower(key){print $2}' | tail -n 1; }
expect_status(){ local label="$1" method="$2" url="$3" expected="$4"; local actual; actual=$(call "$method" "$url"); [[ "$actual" == "$expected" ]] && pass_case "$label" || fail_case "$label" "$method" "$url" "$actual" "$expected"; }
expect_header(){ local label="$1" method="$2" url="$3" expected="$4"; local actual; actual=$(call "$method" "$url"); [[ "$(status_header x-cache)" == "$expected" ]] && pass_case "$label" || fail_case "$label" "$method" "$url" "$actual" "x-cache=$expected"; }
for route in "gateway health|GET|$BASE_URL/health|200" "aggregate health|GET|$BASE_URL/api/health|200" "auth routing|GET|$BASE_URL/api/auth/health|200" "families routing|GET|$BASE_URL/api/families/health|200" "inventory routing|GET|$BASE_URL/api/inventory/health|200" "nutrition routing|GET|$BASE_URL/api/nutrition/health|200" "meal-diary routing|GET|$BASE_URL/api/meal-diary/health|200" "recipes routing|GET|$BASE_URL/api/recipes/health|200" "menus routing|GET|$BASE_URL/api/menus/health|200" "shopping-list routing|GET|$BASE_URL/api/shopping-list/health|200" "payments routing|GET|$BASE_URL/api/payments/health|200" "notifications routing|GET|$BASE_URL/api/notifications/health|200" "admin routing|GET|$BASE_URL/api/admin/health|200" "unknown route|GET|$BASE_URL/api/unknown-route|404"; do IFS='|' read -r label method url expected <<< "$route"; expect_status "$label" "$method" "$url" "$expected"; done
key="e2e-$(date +%s%N)"; cache_url="$BASE_URL/api/notifications/promotions?active=true&e2e=$key"; first=$(call GET "$cache_url"); first_cache=$(status_header x-cache); second=$(call GET "$cache_url"); second_cache=$(status_header x-cache); [[ "$first" == 200 && "$first_cache" == MISS ]] && pass_case 'cache MISS on first public GET' || fail_case 'cache MISS on first public GET' GET "$cache_url" "$first" '200/x-cache=MISS'; [[ "$second" == 200 && "$second_cache" == HIT ]] && pass_case 'cache HIT on second public GET' || fail_case 'cache HIT on second public GET' GET "$cache_url" "$second" '200/x-cache=HIT'; expect_header 'authenticated GET bypasses cache' GET "$cache_url" BYPASS; expect_header 'POST bypasses cache' POST "$cache_url" BYPASS
partner_status=$(call POST "$NOTIFICATION_URL/partners" -H "x-api-key: $API_KEY" -H 'content-type: application/json' -d '{"name":"e2e-partner"}'); partner_id=$(sed -n 's/.*"id":"\([^"]*\)".*/\1/p' "$body_file"); [[ "$partner_status" == 200 || "$partner_status" == 201 ]] && pass_case 'promotion partner upsert' || fail_case 'promotion partner upsert' POST "$NOTIFICATION_URL/partners" "$partner_status" '200 or 201'; device_status=$(call POST "$NOTIFICATION_URL/device-tokens" -H 'content-type: application/json' -d '{"userId":"e2e-user-001","token":"e2e-device-token","platform":"ANDROID"}'); [[ "$device_status" == 201 ]] && pass_case 'promotion device token registration' || fail_case 'promotion device token registration' POST "$NOTIFICATION_URL/device-tokens" "$device_status" 201
promotion_id=''; if [[ -n "$partner_id" ]]; then promotion_status=$(call POST "$NOTIFICATION_URL/partners/$partner_id/promotions" -H "x-api-key: $API_KEY" -H 'content-type: application/json' -d '[{"title":"e2e-promotion","description":"e2e promotion","productKeywords":["ca chua"],"startsAt":"2026-01-01T00:00:00Z","endsAt":"2099-01-01T00:00:00Z"}]'); promotion_id=$(sed -n 's/.*"id":"\([^"]*\)".*/\1/p' "$body_file"); [[ "$promotion_status" == 201 ]] && pass_case 'promotion ingestion' || fail_case 'promotion ingestion' POST "$NOTIFICATION_URL/partners/$partner_id/promotions" "$promotion_status" 201; else promotion_status=0; fail_case 'promotion ingestion' POST "$NOTIFICATION_URL/partners/<missing>/promotions" 0 201; fi
if [[ -n "$promotion_id" ]]; then match_status=$(call POST "$NOTIFICATION_URL/promotions/match" -H 'content-type: application/json' -d '{"userId":"e2e-user-001","keywords":["Cà Chua"]}'); [[ "$match_status" == 200 && "$(cat "$body_file")" == *"$promotion_id"* ]] && pass_case 'promotion keyword match' || fail_case 'promotion keyword match' POST "$NOTIFICATION_URL/promotions/match" "$match_status" 200; dispatch_status=$(call POST "$NOTIFICATION_URL/promotions/$promotion_id/dispatch" -H 'content-type: application/json' -d '{"userIds":["e2e-user-001"]}'); [[ "$dispatch_status" == 200 ]] && pass_case 'promotion mock dispatch' || fail_case 'promotion mock dispatch' POST "$NOTIFICATION_URL/promotions/$promotion_id/dispatch" "$dispatch_status" 200; notification_status=$(call GET "$NOTIFICATION_URL/notifications?userId=e2e-user-001"); [[ "$notification_status" == 200 && "$(cat "$body_file")" == *'"status":"SENT"'* ]] && pass_case 'promotion notification is SENT' || fail_case 'promotion notification is SENT' GET "$NOTIFICATION_URL/notifications?userId=e2e-user-001" "$notification_status" 200; else fail_case 'promotion keyword match' POST "$NOTIFICATION_URL/promotions/<missing>/match" 0 200; fail_case 'promotion mock dispatch' POST "$NOTIFICATION_URL/promotions/<missing>/dispatch" 0 200; fail_case 'promotion notification is SENT' GET "$NOTIFICATION_URL/notifications?userId=e2e-user-001" 0 200; fi
call DELETE "$NOTIFICATION_URL/device-tokens/e2e-device-token" >/dev/null
admin_args=(-H 'x-user-id: e2e-admin-001' -H 'x-user-role: ADMIN'); forbidden=$(call GET "$ADMIN_URL/weights"); [[ "$forbidden" == 403 ]] && pass_case 'admin guard rejects missing role' || fail_case 'admin guard rejects missing role' GET "$ADMIN_URL/weights" "$forbidden" 403
ingredient_status=$(call GET "$ADMIN_URL/ingredients?search=e2e-ingredient" "${admin_args[@]}"); ingredient_id=$(sed -n 's/.*"id":"\([^"]*\)".*/\1/p' "$body_file" | head -n 1); if [[ -z "$ingredient_id" ]]; then ingredient_status=$(call POST "$ADMIN_URL/ingredients" "${admin_args[@]}" -H 'content-type: application/json' -d '{"name":"e2e-ingredient","category":"e2e","defaultUnit":"g","caloriesPer100g":10,"proteinPer100g":1,"carbsPer100g":1,"fatPer100g":1,"allergenTags":[]}'); ingredient_id=$(sed -n 's/.*"id":"\([^"]*\)".*/\1/p' "$body_file"); [[ "$ingredient_status" == 201 ]] && pass_case 'admin ingredient create' || fail_case 'admin ingredient create' POST "$ADMIN_URL/ingredients" "$ingredient_status" 201; else pass_case 'admin ingredient is reusable'; fi
if [[ -n "$ingredient_id" ]]; then update=$(call PUT "$ADMIN_URL/ingredients/$ingredient_id" "${admin_args[@]}" -H 'content-type: application/json' -d '{"category":"e2e-updated"}'); [[ "$update" == 200 ]] && pass_case 'admin ingredient update' || fail_case 'admin ingredient update' PUT "$ADMIN_URL/ingredients/$ingredient_id" "$update" 200; soft=$(call PATCH "$ADMIN_URL/ingredients/$ingredient_id/active" "${admin_args[@]}" -H 'content-type: application/json' -d '{"isActive":false}'); [[ "$soft" == 200 ]] && pass_case 'admin ingredient soft delete' || fail_case 'admin ingredient soft delete' PATCH "$ADMIN_URL/ingredients/$ingredient_id/active" "$soft" 200; call PATCH "$ADMIN_URL/ingredients/$ingredient_id/active" "${admin_args[@]}" -H 'content-type: application/json' -d '{"isActive":true}' >/dev/null; else fail_case 'admin ingredient update' PUT "$ADMIN_URL/ingredients/<missing>" 0 200; fail_case 'admin ingredient soft delete' PATCH "$ADMIN_URL/ingredients/<missing>/active" 0 200; fi
weight_status=$(call GET "$ADMIN_URL/weights/expiry_priority" "${admin_args[@]}"); old_version=$(sed -n 's/.*"version":\([0-9]*\).*/\1/p' "$body_file"); if [[ -n "$old_version" ]]; then updated=$(call PUT "$ADMIN_URL/weights/expiry_priority" "${admin_args[@]}" -H 'content-type: application/json' -d "{\"value\":0.36,\"expectedVersion\":$old_version}"); [[ "$updated" == 200 ]] && pass_case 'admin weight update' || fail_case 'admin weight update' PUT "$ADMIN_URL/weights/expiry_priority" "$updated" 200; stale=$(call PUT "$ADMIN_URL/weights/expiry_priority" "${admin_args[@]}" -H 'content-type: application/json' -d "{\"value\":0.35,\"expectedVersion\":$old_version}"); [[ "$stale" == 409 ]] && pass_case 'admin stale weight update is conflict' || fail_case 'admin stale weight update is conflict' PUT "$ADMIN_URL/weights/expiry_priority" "$stale" 409; call POST "$ADMIN_URL/weights/reset-defaults" "${admin_args[@]}" -H 'content-type: application/json' -d '{}' >/dev/null; else fail_case 'admin weight update' GET "$ADMIN_URL/weights/expiry_priority" "$weight_status" 200; fail_case 'admin stale weight update is conflict' GET "$ADMIN_URL/weights/expiry_priority" "$weight_status" 409; fi
printf '\n%s passed, %s failed, %s skipped\n' "$passed" "$failed" "$skipped"; [[ "$failed" -eq 0 ]]
